-- GlyControl - TACO seed for PostgreSQL/Supabase
-- Fonte: TACO 4ª edição, NEPA/UNICAMP.
-- Reprodução total ou parcial permitida desde que a fonte seja citada.
-- Valores nutricionais por 100 g de parte comestível.

create table if not exists foods (
  food_id text primary key,
  taco_num integer unique,
  nome text not null,
  nome_busca text not null,
  categoria text,
  porcao_base_g numeric not null default 100,
  apto_calculo boolean not null default false,
  fonte text not null
);

create table if not exists nutrients (
  nutrient_id text primary key,
  nome text not null,
  unidade text not null,
  grupo text,
  papel_no_app text,
  base text
);

create table if not exists food_nutrients (
  food_id text not null references foods(food_id) on delete cascade,
  nutrient_id text not null references nutrients(nutrient_id) on delete cascade,
  valor_num_100g numeric,
  valor_calculo_100g numeric,
  valor_original text,
  status_dado text,
  unidade text not null,
  fonte text not null,
  primary key (food_id, nutrient_id)
);

create table if not exists food_portions (
  portion_id text primary key,
  food_id text not null references foods(food_id) on delete cascade,
  descricao text not null,
  peso_g numeric not null,
  fonte text,
  observacao text
);

create index if not exists foods_nome_busca_idx on foods (nome_busca);
create index if not exists foods_categoria_idx on foods (categoria);
create index if not exists food_nutrients_nutrient_idx on food_nutrients (nutrient_id);

on conflict (nutrient_id) do update set nome=excluded.nome,unidade=excluded.unidade,grupo=excluded.grupo,papel_no_app=excluded.papel_no_app,base=excluded.base;

